mapper.insert:
           INSERT INTO TB_SYS_INFO
           (
             SYS_CD
            ,P_SYS_CD			
            ,SYS_TP
            ,SYS_NM		
            ,SYS_DS_LST		
            ,SYS_DESC
            ,DICT_ID
            ,CRET_DT
            ,CRET_USER_ID
           )
           VALUES
           (
             #{sysCd}
            ,#{parentSysCd}
            ,#{sysTp}
            ,#{sysNm}
			      ,#{sysDsLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
            ,#{sysDesc, jdbcType=VARCHAR}
            ,#{dictId, jdbcType=VARCHAR}
            ,to_char(now(), 'YYYYMMDDHH24MISS')
            ,#{cretUserId, jdbcType=VARCHAR}
           )
           ON CONFLICT (SYS_CD) DO UPDATE
            SET
               P_SYS_CD = #{parentSysCd}
              ,SYS_TP = #{sysTp}
              ,SYS_NM = #{sysNm}
              ,SYS_DS_LST = #{sysDsLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
              ,SYS_DESC = #{sysDesc, jdbcType=VARCHAR}
              ,DICT_ID = #{dictId, jdbcType=VARCHAR}
              ,UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS')
              ,UPDT_USER_ID = #{updtUserId}

mapper.update:
UPDATE
  TB_SYS_INFO
SET
   P_SYS_CD = #{parentSysCd}
  ,SYS_TP = #{sysTp}
  ,SYS_NM = #{sysNm}
  ,SYS_DS_LST = #{sysDsLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
  ,SYS_DESC = #{sysDesc, jdbcType=VARCHAR}
  ,DICT_ID = #{dictId, jdbcType=VARCHAR}
  ,UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS')
  ,UPDT_USER_ID = #{updtUserId}
WHERE
  SYS_CD = #{sysCd}

mapper.delete:
with recursive CODE_LIST(SYS_CD, P_SYS_CD, SYS_TP, SYS_NM, SYS_DS_LST, SYS_DESC, DEPTH, PATH, CYCLE) as ( select A.SYS_CD, A.P_SYS_CD, A.SYS_TP, A.SYS_NM, A.SYS_DS_LST, A.SYS_DESC, 1, array[A.SYS_NM::text], false from TB_SYS_INFO A where A.SYS_CD IN
#{item.sysCd}
union all select A.SYS_CD, A.P_SYS_CD, A.SYS_TP, A.SYS_NM, A.SYS_DS_LST, A.SYS_DESC, B.DEPTH + 1, array_append(B.PATH,A.SYS_NM::text), A.SYS_CD = any(B.PATH) from TB_SYS_INFO A, CODE_LIST B where A.P_SYS_CD = B.SYS_CD and not CYCLE ) DELETE FROM TB_SYS_INFO WHERE SYS_CD IN (SELECT SYS_CD FROM CODE_LIST)

mapper.insert:
INSERT INTO ndata.tb_data_source
(
  DS_ID
 ,DSN
 ,DS_TP
 ,DBMS_TP
 ,DRIVER_NM
 ,SVR_ADDR
 ,PORT
 ,USER_ID
 ,PWD
 ,CHARSET
 ,PRIVATE_KEY
 ,DB_NAME
 ,RM_DIR
 ,CONN_PROPS
 ,SECURE_YN
)
VALUES
(
  #{id}
 ,#{dsn}
 ,#{dsTp, jdbcType=SMALLINT}
 ,#{dbmsTp, jdbcType=VARCHAR}
 ,#{driverName, jdbcType=VARCHAR}
 ,#{svrAddr}
 ,#{port}
 ,#{userId, jdbcType=VARCHAR}
 ,#{pwd, jdbcType=VARCHAR}
 ,#{charSet, jdbcType=VARCHAR}
 ,#{privateKey, jdbcType=VARCHAR}
 ,#{dbName, jdbcType=VARCHAR}
 ,#{rmDir, jdbcType=VARCHAR}
 ,#{connProps, jdbcType=VARCHAR}
 ,#{useSecure, jdbcType=BOOLEAN}
)

mapper.update:
UPDATE
  ndata.tb_data_source
SET
    DSN = #{dsn}
   ,DS_TP = #{dsTp}
   ,DBMS_TP = #{dbmsTp}
   ,DRIVER_NM = #{driverName}
   ,SVR_ADDR = #{svrAddr}
   ,PORT = #{port}
   ,USER_ID = #{userId}


   ,PWD = #{pwd}

   ,CHARSET = #{charSet}
   ,PRIVATE_KEY = #{privateKey}
   ,DB_NAME = #{dbName}
   ,RM_DIR = #{rmDir}
   ,CONN_PROPS = #{connProps}
   ,SECURE_YN = #{useSecure}
   ,CONN_TEST_YN = 'N'
   ,CONN_TEST_DT = NULL
WHERE
  DS_ID = #{id}

UPDATE ndata.tb_data_source
SET CONN_TEST_YN = 'Y', CONN_TEST_DT = NOW()
WHERE DS_ID = #{id}

mapper.select:
SELECT R.* FROM ( SELECT S.DSN as "dsn" ,(SELECT string_agg(DISTINCT M.DM_NM, '·' ORDER BY M.DM_NM) FROM TB_DATA_MODEL M WHERE M.DM_DS_ID = S.DS_ID AND (M.USE_YN = 'Y' OR M.USE_YN IS NULL)) as "models" ,(SELECT string_agg(I.SYS_NM, '·' ORDER BY I.SYS_NM) FROM TB_SYS_INFO I WHERE S.DS_ID = ANY(I.SYS_DS_LST)) as "systems" FROM ndata.tb_data_source S WHERE S.DS_ID IN
#{item.id}
) R WHERE R."models" IS NOT NULL OR R."systems" IS NOT NULL ORDER BY R."dsn"

mapper.delete:
WITH GOV AS (
    DELETE FROM TB_GOV_META_DB
     WHERE DS_ID IN

           #{item.id}

)
DELETE FROM ndata.tb_data_source
WHERE
  DS_ID IN

    #{item.id}
